"use strict";(self.webpackChunk_ai_autistic_intelligence_docusaurus_theme=self.webpackChunk_ai_autistic_intelligence_docusaurus_theme||[]).push([["1877"],{3982(e){e.exports=JSON.parse('{"version":{"pluginId":"ferrox-front","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/ferrox-front/architecture","label":"Core WebAssembly System Architecture","docId":"architecture","unlisted":false},{"type":"link","href":"/docs/ferrox-front/intro","label":"Introduction & Ferrox-Front Architecture","docId":"intro","unlisted":false},{"type":"link","href":"/docs/ferrox-front/overview","label":"Overview","docId":"overview","unlisted":false},{"type":"link","href":"/docs/ferrox-front/core","label":"Core Kernel, Context Providers & Resource Managers","docId":"core","unlisted":false},{"type":"link","href":"/docs/ferrox-front/quickstart","label":"Quickstart Guide","docId":"quickstart","unlisted":false},{"type":"link","href":"/docs/ferrox-front/reactivity","label":"Fine-Grained Reactive Primitives (Signals, Memos & Effects)","docId":"reactivity","unlisted":false},{"type":"link","href":"/docs/ferrox-front/macros","label":"Procedural Macros, Component Annotations & Code Generation","docId":"macros","unlisted":false},{"type":"link","href":"/docs/ferrox-front/routing","label":"Client-Side Router, Route Guards & Lazy Loading","docId":"routing","unlisted":false},{"type":"link","href":"/docs/ferrox-front/templates","label":"Virtual DOM Templates, JSX Engine & HTML Macros","docId":"templates","unlisted":false},{"type":"link","href":"/docs/ferrox-front/ui-components","label":"Glassmorphism Design System (ferrox-front-ui)","docId":"ui-components","unlisted":false},{"type":"link","href":"/docs/ferrox-front/components","label":"Component Library & Interactive Playground","docId":"components","unlisted":false},{"type":"link","href":"/docs/ferrox-front/security","label":"Zero-Trust Wasm Security, WebCrypto & XSS Sanitization","docId":"security","unlisted":false},{"type":"link","href":"/docs/ferrox-front/ws","label":"Real-Time WebSockets Engine (ferrox-front-ws)","docId":"ws","unlisted":false}]},"docs":{"architecture":{"id":"architecture","title":"Core WebAssembly System Architecture","description":"The ferrox-front architecture is designed around zero-cost abstractions, fine-grained reactive dependency graphs, single-threaded browser thread execution, WebAssembly linear memory layout, and WebGL rendering acceleration.","sidebar":"tutorialSidebar"},"components":{"id":"components","title":"Component Library & Interactive Playground","description":"Explore and interact with the Ferrox Front component library live in your browser using our Nivo-Style Interactive Playground.","sidebar":"tutorialSidebar"},"core":{"id":"core","title":"Core Kernel, Context Providers & Resource Managers","description":"The ferrox-front-core crate is the foundation kernel of the Ferrox WebAssembly frontend framework. It manages component context providers (providecontext, usecontext), async resource loaders (create_resource), effect batch schedulers, and browser lifecycle event hooks.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Introduction & Ferrox-Front Architecture","description":"Welcome to Ferrox-Front, the high-performance WebAssembly (Wasm) frontend framework written in pure Rust. It combines fine-grained reactive signals, compile-time JSX HTML templates, zero-trust cryptographic security, real-time WebSocket state synchronization, and GPU-accelerated WebGL charts into a unified application suite.","sidebar":"tutorialSidebar"},"macros":{"id":"macros","title":"Procedural Macros, Component Annotations & Code Generation","description":"The ferrox-front-macro crate provides Rust procedural macros (#[component], view!, derive(Store)) that transform declarative UI components and reactive state structs into optimized WebAssembly execution code.","sidebar":"tutorialSidebar"},"overview":{"id":"overview","title":"Overview","description":"Ferrox Front is a high-performance, WebAssembly (WASM) based frontend framework written in Rust, leveraging the Yew framework under the hood. It provides a robust, type-safe environment for building complex User Interfaces while maintaining near-native performance.","sidebar":"tutorialSidebar"},"quickstart":{"id":"quickstart","title":"Quickstart Guide","description":"This guide demonstrates how to install prerequisites, build your first WebAssembly application in Rust using Ferrox Front, and run it in the browser.","sidebar":"tutorialSidebar"},"reactivity":{"id":"reactivity","title":"Fine-Grained Reactive Primitives (Signals, Memos & Effects)","description":"The ferrox-front-core reactivity engine provides fine-grained reactive state management in WebAssembly. Built on push-pull signal graphs, it exposes Signal, ReadSignal, WriteSignal, Memo, and Effect primitives without relying on Virtual DOM diffing.","sidebar":"tutorialSidebar"},"routing":{"id":"routing","title":"Client-Side Router, Route Guards & Lazy Loading","description":"The ferrox-front-router crate delivers client-side SPA navigation for WebAssembly apps. It features HTML5 History API integration, route path parameter matching, nested layout outlets, route protection guards, and code-split WebAssembly module lazy loading.","sidebar":"tutorialSidebar"},"security":{"id":"security","title":"Zero-Trust Wasm Security, WebCrypto & XSS Sanitization","description":"The ferrox-front-security crate delivers zero-trust security for Rust WebAssembly applications. It features browser WebCrypto API bindings (AES-256-GCM, RSA-OAEP, ECDSA), zero-copy linear memory wiping (Zeroize), secure storage adapters, and HTML XSS sanitizers.","sidebar":"tutorialSidebar"},"templates":{"id":"templates","title":"Virtual DOM Templates, JSX Engine & HTML Macros","description":"The ferrox-front-templates crate delivers zero-allocation HTML templating, WebAssembly compile-time JSX expansion, reactive DOM element patching, and SSR (Server-Side Rendering) string interpolation for Rust web applications.","sidebar":"tutorialSidebar"},"ui-components":{"id":"ui-components","title":"Glassmorphism Design System (ferrox-front-ui)","description":"ferrox-front-ui provides a complete, enterprise-grade Glassmorphism Design System for WebAssembly applications. It includes Design Tokens, a 12-column responsive layout grid, a Virtualized DataGrid (1,000,000+ rows), and a comprehensive library of pre-styled UI components.","sidebar":"tutorialSidebar"},"ws":{"id":"ws","title":"Real-Time WebSockets Engine (ferrox-front-ws)","description":"ferrox-front-ws provides an asynchronous WebAssembly WebSocket client engine built natively for Rust frontends. It bridges browser WebSocket APIs (web_sys::WebSocket) with Ferrox Front\'s reactive Signals graph (Signal), enabling low-latency, real-time bi-directional streaming for dashboards, chat applications, financial tickers, and live notification systems.","sidebar":"tutorialSidebar"}}}}')}}]);